/**
 * Cadastra um veículo para o CPF autenticado. Fluxo catálogo (brand_id+model_id) ou Outro (brand_other/model_other+vehicle_type). URLs de foto devem ser HTTPS GCS. Se has_invoice=true, invoice_photo_url é obrigatória. Contato do dono (nome/telefone/e-mail) é enriquecido ao vivo via RMI a partir do owner_cpf — não enviar owner_* no body. registration_number é gerado pelo backend (formato RJ-E-XXXXXX).
 * @summary Cadastrar veículo
 */
export const postCitizenCpfVehicles = async (
  cpf: string,
  modelsVehicleCreateRequest: ModelsVehicleCreateRequest,
  options?: RequestInit
): Promise<postCitizenCpfVehiclesResponse> => {
  return customFetch<postCitizenCpfVehiclesResponse>(
    getPostCitizenCpfVehiclesUrl(cpf),
    {
      ...options,
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...options?.headers },
      body: JSON.stringify(modelsVehicleCreateRequest),
    }
  )
}

