export const getGetMobilidadeVehicleModelsUrl = (
  params: GetMobilidadeVehicleModelsParams
) => {
  const normalizedParams = new URLSearchParams()

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  })

  const stringifiedParams = normalizedParams.toString()

  return stringifiedParams.length > 0
    ? `/mobilidade/vehicle-models?${stringifiedParams}`
    : `/mobilidade/vehicle-models`
}

/**
 * Modelos do catálogo filtrados por brand_id (obrigatório), incluindo vehicle_type. Sentinel "Outro" usa id estável model_outro com is_other=true.
 * @summary Listar modelos de veículos por marca
 */
export const getMobilidadeVehicleModels = async (
  params: GetMobilidadeVehicleModelsParams,
  options?: RequestInit
): Promise<getMobilidadeVehicleModelsResponse> => {
  return customFetch<getMobilidadeVehicleModelsResponse>(
    getGetMobilidadeVehicleModelsUrl(params),
    {
      ...options,
      method: 'GET',
    }
  )
}
